// Simplified from the Command class in the Flutter docs
Future<void> _execute(CommandAction0<T> action) async {
  if (_running) return;
  _running = true;
  _result = null;
  notifyListeners();
  try {
    _result = await action();
  } finally {
    _running = false;
    notifyListeners();
  }
}

